-- RegulaQuest · 27 · Simulace (fáze 1): scénáře, zpřístupnění skupinám, průchody studentů
-- Jen nové tabulky sim_* a nové funkce rq_sim_* – stávající obsah RegulaQuestu se nemění.
-- * Scénář = definice {"version": 1, "module": "vigilance", "title": "Předávkování z infuzní pumpy", "summary": "Nemocnice hlásí, že pumpa podala pacientovi několikanásobek dávky heparinu. Zjistěte, co se stalo, posuďte závažnost, nahlaste a rozhodněte o nápravném opatření – dřív, než se to stane jinde.", "minutes": 30, "role": "Vigilance výrobce – Medivia Systems s.r.o. (fiktivní výrobce)", "clock": "Den {d} od přijetí hlášení", "max_day": 25, "intro": "Jste odpovědní za vigilanci u výrobce infuzních pump. Právě vám přišlo hlášení z nemocnice. Každý krok stojí čas (počet dní je u tlačítka) – lhůty běží od okamžiku, kdy se výrobce o příhodě dozvěděl, tedy ode dne 0. Nic vám nepřipomene termín; hlídejte si ho sami.\n\nVšechny firmy, nemocnice, prostředky a údaje jsou smyšlené.", "start_messages": ["m_hlaseni"], "messages": {"m_hlaseni": {"from": "Krajská nemocnice Lipovec – ARO", "subject": "Podezření na předávkování při použití pumpy InfuSIM P3", "body": "Dobrý den,\n\nhlásíme událost s volumetrickou infuzní pumpou InfuSIM P3 (výrobní číslo SIM-P3-004417).\n\nPacientovi (68 let) byla podávána kontinuální infuze heparinu. Během podávání bolusu sestra upravila rychlost kontinuální infuze. Po zhruba dvou hodinách byla zjištěna výrazně vyšší spotřeba roztoku – pacient dostal přibližně trojnásobek naordinované dávky.\n\nDošlo ke krvácení, pacient potřeboval transfuzi a převoz na JIP. Nyní je stabilizovaný.\n\nPumpu jsme vyřadili z provozu a ponechali v původním stavu. Prosíme o vyjádření.\n\nMUDr. J. Kratochvíl, primář ARO"}, "m_detaily": {"from": "Krajská nemocnice Lipovec – zdravotnická technika", "subject": "Re: doplňující informace k pumpě SIM-P3-004417", "body": "Doplňujeme informace:\n\n- verze softwaru pumpy: 2.3 (nainstalována před třemi týdny při pravidelném servisu),\n- naordinováno 1 000 IU/h, bolus 5 000 IU; sestra během bolusu změnila kontinuální rychlost na 1 200 IU/h,\n- pumpa nehlásila žádný alarm,\n- obsluha byla proškolena, postup odpovídal návodu k použití,\n- pumpa i paměť událostí jsou k dispozici, můžeme ji poslat.\n\nIng. P. Malá, oddělení zdravotnické techniky"}, "m_vraceni": {"from": "Servisní oddělení Medivia", "subject": "Pumpa SIM-P3-004417 přijata", "body": "Pumpa z Lipovce dorazila v neporušeném stavu, protokol událostí jsme stáhli. Můžeme spustit technickou analýzu."}, "m_analyza": {"from": "Vývoj a laboratoř Medivia", "subject": "Výsledek analýzy SIM-P3-004417", "body": "Chybu jsme reprodukovali v laboratoři.\n\nPříčina: ve verzi softwaru 2.3 se při změně kontinuální rychlosti během běžícího bolusu uloží bolusová rychlost jako nová kontinuální rychlost. Pumpa pak pokračuje vysokou rychlostí bez alarmu. Verze 2.2 chybu nemá.\n\nOpravenou verzi 2.4 umíme připravit a ověřit do 10 dnů. Do té doby chybě zabrání, pokud obsluha během bolusu kontinuální rychlost nemění.\n\nPozn.: v analýze rizik je nadměrné podání (over-infusion) uvedeno jako identifikované nebezpečí."}, "m_baze": {"from": "Obchodní oddělení Medivia", "subject": "Pumpy InfuSIM P3 v provozu", "body": "Podle evidence servisu a prodeje:\n\n- v provozu je 412 pump InfuSIM P3 (Česko a Slovensko),\n- 286 z nich má software 2.3 (14 nemocnic), aktualizace se instaluje při servisu od začátku minulého měsíce,\n- 126 pump má ještě verzi 2.2.\n\nSeznam nemocnic a výrobních čísel je připravený."}, "m_trend": {"from": "Oddělení kvality Medivia", "subject": "Podobné stížnosti za poslední rok", "body": "Za poslední měsíc jsme evidovali dvě stížnosti „pumpa P3 podává rychleji, než bylo nastaveno“ (obě s verzí 2.3). Bez újmy pacientům, uzavřeno jako chyba obsluhy a doškoleno.\n\nV kontextu dnešního hlášení je to zjevně stejný problém."}, "m_mir_ok": {"from": "SÚKL – vigilance zdravotnických prostředků (simulace)", "subject": "Potvrzení přijetí hlášení", "body": "Potvrzujeme přijetí vašeho hlášení. Očekáváme další informace o výsledku šetření, případně konečnou zprávu."}, "m_fsca_ok": {"from": "Vigilance Medivia", "subject": "Bezpečnostní nápravné opatření zahájeno", "body": "Opatření je zahájeno podle vašeho rozhodnutí. Nezapomeňte na bezpečnostní upozornění (FSN) pro uživatele."}, "m_fsn_ok": {"from": "Vigilance Medivia", "subject": "Bezpečnostní upozornění odesláno", "body": "Bezpečnostní upozornění bylo rozesláno dotčeným nemocnicím. Sledujeme potvrzení o přijetí."}, "m_final_ok": {"from": "SÚKL – vigilance zdravotnických prostředků (simulace)", "subject": "Konečná zpráva přijata", "body": "Konečnou zprávu jsme přijali. Případ budeme dál sledovat v rámci dozoru nad trhem."}, "m_pripominka": {"from": "Krajská nemocnice Lipovec – ARO", "subject": "Stále čekáme na vaše vyjádření", "body": "Dobrý den, od našeho hlášení uplynulo několik dní a zatím jsme od vás nedostali žádnou reakci ani žádost o doplnění. Pumpa je stále vyřazená z provozu."}, "m_druha": {"from": "Nemocnice Bor – interní JIP", "subject": "Závažná událost s pumpou InfuSIM P3", "body": "Hlásíme úmrtí pacientky (81 let) po krvácení při léčbě heparinem. Pumpa InfuSIM P3 (výrobní číslo SIM-P3-003902, software 2.3) podle záznamu podala výrazně vyšší dávku, než bylo nastaveno – během bolusu byla měněna rychlost. Pumpu uchováváme pro šetření."}, "m_sukl": {"from": "SÚKL – vigilance zdravotnických prostředků (simulace)", "subject": "Výzva k vysvětlení", "body": "Od poskytovatele zdravotních služeb jsme obdrželi informaci o závažné nežádoucí příhodě s pumpou InfuSIM P3, ke které od vás nemáme hlášení. Vyzýváme vás k bezodkladnému vysvětlení. Zahajujeme kontrolu plnění povinností výrobce."}, "m_druha_ok": {"from": "SÚKL – vigilance zdravotnických prostředků (simulace)", "subject": "Potvrzení přijetí hlášení (Nemocnice Bor)", "body": "Potvrzujeme přijetí hlášení k události v Nemocnici Bor."}}, "actions": [{"id": "a_detaily", "group": "Zjistit víc", "label": "Vyžádat si podrobnosti od nemocnice", "days": 1, "messages": ["m_detaily"]}, {"id": "a_vraceni", "group": "Zjistit víc", "label": "Vyžádat vrácení pumpy a protokolu událostí", "days": 3, "set": {"pump_returned": true}, "messages": ["m_vraceni"]}, {"id": "a_analyza", "group": "Zjistit víc", "label": "Technická analýza pumpy", "days": 2, "when": {"done": "a_vraceni"}, "need": "Nejdřív potřebujete pumpu z nemocnice.", "set": {"root_cause": true}, "messages": ["m_analyza"]}, {"id": "a_baze", "group": "Zjistit víc", "label": "Zjistit, kolik pump a s jakým softwarem je v provozu", "days": 1, "messages": ["m_baze"]}, {"id": "a_trend", "group": "Zjistit víc", "label": "Prověřit podobné stížnosti z poslední doby", "days": 1, "messages": ["m_trend"]}, {"id": "a_zavaznost", "group": "Posoudit a nahlásit", "label": "Posoudit závažnost události", "days": 0, "choice": {"prompt": "Jak událost z Lipovce vyhodnotíte?", "var": "severity", "options": [{"id": "serious", "label": "Závažná nežádoucí příhoda – vedla k vážnému zhoršení zdravotního stavu pacienta"}, {"id": "threat", "label": "Závažné ohrožení veřejného zdraví"}, {"id": "nonserious", "label": "Nežádoucí příhoda, která není závažná – zaznamenat a sledovat v trendech"}, {"id": "user", "label": "Chyba obsluhy – nehlásit, vyřešit doškolením"}]}}, {"id": "a_mir", "group": "Posoudit a nahlásit", "label": "Podat hlášení příslušnému orgánu (SÚKL)", "days": 0, "messages": ["m_mir_ok"], "form": {"title": "Hlášení závažné nežádoucí příhody (zjednodušený formulář)", "intro": "Simulace hlášení výrobce. Uveďte, co o případu víte – počáteční hlášení může být neúplné a doplní se.", "fields": [{"id": "type", "label": "Typ hlášení", "type": "select", "options": [{"id": "initial", "label": "Počáteční"}, {"id": "combined", "label": "Kombinované počáteční a konečné"}, {"id": "final", "label": "Konečné"}]}, {"id": "class", "label": "Klasifikace", "type": "select", "options": [{"id": "serious", "label": "Závažná nežádoucí příhoda"}, {"id": "threat", "label": "Závažné ohrožení veřejného zdraví"}, {"id": "death", "label": "Úmrtí nebo nepředvídané vážné zhoršení zdravotního stavu"}]}, {"id": "content", "label": "Co hlášení obsahuje", "type": "checks", "options": [{"id": "event", "label": "Popis události a důsledků pro pacienta"}, {"id": "device", "label": "Identifikace prostředku (typ, výrobní číslo, verze softwaru)"}, {"id": "provider", "label": "Kdo událost ohlásil (poskytovatel)"}, {"id": "cause", "label": "Předběžné hodnocení příčiny (je-li známo)"}, {"id": "steps", "label": "Další plánované kroky šetření"}]}]}}, {"id": "a_mir2", "group": "Posoudit a nahlásit", "label": "Nahlásit událost z Nemocnice Bor", "days": 0, "when": {"flag": "second_incident"}, "need": "Zatím není co hlásit.", "messages": ["m_druha_ok"], "form": {"title": "Hlášení k události v Nemocnici Bor", "fields": [{"id": "class", "label": "Klasifikace", "type": "select", "options": [{"id": "serious", "label": "Závažná nežádoucí příhoda"}, {"id": "threat", "label": "Závažné ohrožení veřejného zdraví"}, {"id": "death", "label": "Úmrtí nebo nepředvídané vážné zhoršení zdravotního stavu"}]}]}}, {"id": "a_fsca", "group": "Nápravná opatření", "label": "Zahájit bezpečnostní nápravné opatření (FSCA)", "days": 2, "messages": ["m_fsca_ok"], "set": {"fsca": true}, "form": {"title": "Bezpečnostní nápravné opatření (FSCA)", "fields": [{"id": "measure", "label": "Opatření", "type": "select", "options": [{"id": "sw", "label": "Aktualizace na opravenou verzi softwaru; do té doby pokyn neměnit rychlost během bolusu"}, {"id": "recall", "label": "Stáhnout z trhu všechny pumpy InfuSIM P3"}, {"id": "warn", "label": "Jen upozornit uživatele, bez technického řešení"}]}, {"id": "scope", "label": "Kterých pump se týká", "type": "select", "options": [{"id": "v23", "label": "Pump se softwarem 2.3"}, {"id": "all", "label": "Všech pump InfuSIM P3"}, {"id": "one", "label": "Jen pumpy z Lipovce"}]}, {"id": "notify", "label": "Příslušný orgán", "type": "checks", "options": [{"id": "before", "label": "Oznámit opatření příslušnému orgánu před jeho zahájením"}]}]}}, {"id": "a_fsn", "group": "Nápravná opatření", "label": "Připravit bezpečnostní upozornění (FSN) pro uživatele", "days": 1, "when": {"done": "a_fsca"}, "need": "Nejdřív rozhodněte o nápravném opatření.", "messages": ["m_fsn_ok"], "form": {"title": "Bezpečnostní upozornění (FSN)", "intro": "Vyberte, co do upozornění patří.", "fields": [{"id": "content", "label": "Obsah upozornění", "type": "checks", "options": [{"id": "ident", "label": "Identifikace dotčených pump (typ, verze softwaru, výrobní čísla)"}, {"id": "problem", "label": "Popis problému a rizika pro pacienty"}, {"id": "now", "label": "Co mají uživatelé udělat hned (neměnit rychlost během bolusu)"}, {"id": "plan", "label": "Opatření výrobce a termín aktualizace"}, {"id": "forward", "label": "Žádost o předání všem uživatelům a potvrzení přijetí"}, {"id": "contact", "label": "Kontakt na výrobce"}, {"id": "discount", "label": "Omluva a sleva na příští nákup"}, {"id": "blame", "label": "Upozornění, že jde o chybu obsluhy"}]}]}}, {"id": "a_final", "group": "Posoudit a nahlásit", "label": "Podat konečnou zprávu", "days": 1, "when": {"all": [{"done": "a_mir"}, {"flag": "root_cause"}]}, "need": "Konečná zpráva předpokládá podané hlášení a známou příčinu.", "messages": ["m_final_ok"]}, {"id": "a_wait", "group": "Čas", "label": "Počkat jeden den", "days": 1, "repeat": true}, {"id": "a_close", "group": "Čas", "label": "Uzavřít případ a zobrazit rozbor", "days": 0, "end": true, "confirm": "Opravdu uzavřít? Další kroky už nepůjdou udělat."}], "events": [{"id": "e_pripominka", "when": {"all": [{"day_gte": 3}, {"not": {"done": "a_detaily"}}]}, "messages": ["m_pripominka"]}, {"id": "e_druha", "when": {"all": [{"day_gte": 12}, {"not": {"done": "a_fsca"}}]}, "set": {"second_incident": true}, "messages": ["m_druha"]}, {"id": "e_sukl", "when": {"all": [{"day_gte": 16}, {"not": {"done": "a_mir"}}]}, "set": {"inspection": true}, "messages": ["m_sukl"]}, {"id": "e_konec", "when": {"day_gte": 25}, "end": true}], "rules": [{"id": "r_class", "label": "Událost jste vyhodnotili jako závažnou nežádoucí příhodu", "ok": {"var": "severity", "eq": "serious"}, "good": "Pacient potřeboval transfuzi a převoz na JIP – vážné zhoršení zdravotního stavu, tedy závažná nežádoucí příhoda.", "bad": "Pacient potřeboval transfuzi a převoz na JIP – jde o vážné zhoršení zdravotního stavu, tedy závažnou nežádoucí příhodu. Nejde o chybu obsluhy (postup odpovídal návodu) ani o „nezávažnou“ příhodu; závažné ohrožení veřejného zdraví by vyžadovalo riziko pro širokou populaci.", "refs": ["MDR|Článek 2", "MDCG 2023-3"]}, {"id": "r_mir", "label": "Hlášení podáno nejpozději 15. den od přijetí informace", "ok": {"done_by": {"action": "a_mir", "day_lte": 15}}, "good": "Výrobce hlásí bezodkladně, jakmile je souvislost s prostředkem prokázaná nebo přiměřeně možná, nejpozději do 15 dnů. Na úplné výsledky šetření se nečeká – podá se počáteční hlášení.", "bad": "Lhůta běží ode dne, kdy se výrobce o příhodě dozvěděl. Hlásí se bezodkladně, nejpozději do 15 dnů – i s neúplnými informacemi (počáteční hlášení), výsledky šetření se doplní.", "refs": ["MDR|Článek 87"]}, {"id": "r_mir_class", "label": "V hlášení správná klasifikace", "only_if": {"done": "a_mir"}, "ok": {"var": "form.a_mir.class", "eq": "serious"}, "good": "Správně: závažná nežádoucí příhoda (riziko nadměrného podání je v analýze rizik uvedené, nejde tedy o nepředvídané zhoršení).", "bad": "Správná klasifikace je závažná nežádoucí příhoda. Kratší lhůty platí pro závažné ohrožení veřejného zdraví a pro úmrtí či nepředvídané vážné zhoršení zdravotního stavu.", "refs": ["MDR|Článek 87"]}, {"id": "r_info", "label": "Před rozhodováním jste si vyžádali podrobnosti", "ok": {"done": "a_detaily"}, "good": "Podrobnosti (verze softwaru, postup obsluhy) navedly šetření správným směrem.", "bad": "Bez podrobností od nemocnice nevíte o verzi softwaru ani o postupu obsluhy – a šetření se snadno stočí k „chybě obsluhy“.", "refs": ["MDR|Článek 89"]}, {"id": "r_root", "label": "Zjistili jste příčinu (technická analýza)", "ok": {"flag": "root_cause"}, "good": "Analýza odhalila chybu softwaru 2.3 – bez ní by nápravné opatření mířilo naslepo.", "bad": "Bez analýzy vrácené pumpy příčinu neznáte; výrobce musí provést šetření příhody včetně posouzení prostředku.", "refs": ["MDR|Článek 89"]}, {"id": "r_trend", "label": "Prověřili jste podobné stížnosti", "ok": {"done": "a_trend"}, "good": "Dvě dřívější stížnosti uzavřené jako „chyba obsluhy“ byly ve skutečnosti varovný signál.", "bad": "V evidenci byly dvě podobné stížnosti uzavřené jako chyba obsluhy. Sledování trendů je povinnost výrobce a pomáhá odhalit problém dřív.", "refs": ["MDR|Článek 88"]}, {"id": "r_scope", "label": "Rozsah (kolik pump a s jakým softwarem) jste znali před opatřením", "only_if": {"done": "a_fsca"}, "ok": {"done_before": ["a_baze", "a_fsca"]}, "good": "Opatření jste cílili na skutečně dotčené pumpy.", "bad": "Bez znalosti rozsahu nevíte, koho opatření týká – hrozí příliš úzké nebo zbytečně široké opatření."}, {"id": "r_fsca_time", "label": "Nápravné opatření zahájeno včas (do 11. dne)", "ok": {"done_by": {"action": "a_fsca", "day_lte": 11}}, "good": "Včasné opatření zabránilo další příhodě.", "bad": "Bez včasného opatření se stejná chyba projevila v jiné nemocnici. Ochrana dalších pacientů nečeká na dokončení všech analýz.", "refs": ["MDR|Článek 89"]}, {"id": "r_fsca_measure", "label": "Přiměřené opatření a správný rozsah", "only_if": {"done": "a_fsca"}, "ok": {"all": [{"var": "form.a_fsca.measure", "eq": "sw"}, {"var": "form.a_fsca.scope", "eq": "v23"}]}, "good": "Aktualizace softwaru u pump s verzí 2.3 a do té doby jasný pokyn – cílené a přiměřené.", "bad": "Příčina je v softwaru 2.3: přiměřené je opravit software u dotčených pump a do té doby dát uživatelům pokyn. Stažení všech pump by zbytečně ohrozilo péči, samotné upozornění bez opravy problém neodstraní."}, {"id": "r_fsca_notify", "label": "FSCA oznámeno příslušnému orgánu předem", "only_if": {"done": "a_fsca"}, "ok": {"var": "form.a_fsca.notify", "has": "before"}, "good": "Nápravné opatření se příslušnému orgánu oznamuje před jeho zahájením (kromě naléhavých případů).", "bad": "Nápravné opatření se příslušnému orgánu oznamuje před jeho zahájením, kromě naléhavých případů.", "refs": ["MDR|Článek 87", "MDR|Článek 89"]}, {"id": "r_fsn", "label": "Bezpečnostní upozornění obsahuje, co má", "only_if": {"done": "a_fsca"}, "ok": {"all": [{"var": "form.a_fsn.content", "has_all": ["ident", "problem", "now", "plan", "forward", "contact"]}, {"not": {"var": "form.a_fsn.content", "has_any": ["discount", "blame"]}}]}, "good": "Upozornění jednoznačně identifikuje pumpy, vysvětluje riziko a říká, co dělat.", "bad": "FSN má identifikovat dotčené prostředky, popsat problém a riziko, říct uživatelům, co mají dělat, uvést opatření výrobce, požádat o předání a dát kontakt. Obchodní nabídky ani svalování viny na obsluhu do něj nepatří.", "refs": ["MDR|Článek 89"]}, {"id": "r_second", "label": "Událost z Nemocnice Bor nahlášena do 10 dnů", "only_if": {"flag": "second_incident"}, "ok": {"within": {"action": "a_mir2", "from_flag": "second_incident", "days": 10}}, "good": "U úmrtí platí kratší lhůta – nejpozději 10 dnů.", "bad": "U úmrtí nebo nepředvídaného vážného zhoršení zdravotního stavu je lhůta kratší – nejpozději 10 dnů.", "refs": ["MDR|Článek 87"]}, {"id": "r_final", "label": "Podána konečná zpráva", "ok": {"done": "a_final"}, "good": "Šetření je uzavřené konečnou zprávou s příčinou a opatřeními.", "bad": "Po dokončení šetření výrobce podává konečnou zprávu se závěry a přijatými opatřeními.", "refs": ["MDR|Článek 89"]}, {"id": "r_noharm", "label": "Nedošlo k další příhodě", "ok": {"not": {"flag": "second_incident"}}, "good": "Další pacienti nebyli poškozeni.", "bad": "Chyba se projevila znovu a pacientka zemřela. Rozhodující bylo včasné opatření."}], "outcomes": [{"min": 90, "label": "Výborně zvládnuto", "text": "Postupovali jste jako zkušený výrobce: včas jste hlásili, našli příčinu a cíleně ochránili další pacienty."}, {"min": 65, "label": "Zvládnuto s výhradami", "text": "Hlavní kroky jste udělali, ale v něčem jste zaváhali – podívejte se na body níže."}, {"min": 0, "label": "Nezvládnuto", "text": "Některé zásadní povinnosti zůstaly nesplněné. Zkuste případ znovu a zaměřte se na lhůty a ochranu pacientů."}]} (zprávy, akce, události, pravidla hodnocení); jádro běží v prohlížeči (sdilene/simulace.js).
-- * Průchod patří účtu (aby šel přerušit a dokončit); Studio z průchodů ukazuje jen souhrny bez účtů.
-- * Studenti vidí scénář ve stavu „připraveno“ zpřístupněný jejich skupině (od data), stejně jako prezentace.
-- Lze spustit opakovaně.

create table if not exists public.sim_scenarios (
  id          text primary key,
  module      text not null default 'vigilance',
  title       text not null,
  summary     text not null default '',
  status      text not null default 'draft' check (status in ('draft', 'ready')),
  definition  jsonb not null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  updated_by  uuid
);
create table if not exists public.sim_scenario_groups (
  scenario_id  text not null references public.sim_scenarios(id) on delete cascade,
  group_id     uuid not null references public.student_groups(id) on delete cascade,
  visible_from date not null default current_date,
  primary key (scenario_id, group_id)
);
create table if not exists public.sim_runs (
  id          uuid primary key default gen_random_uuid(),
  scenario_id text not null references public.sim_scenarios(id) on delete cascade,
  user_id     uuid not null references auth.users(id) on delete cascade,
  is_admin    boolean not null default false,
  started_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  finished_at timestamptz,
  state       jsonb not null,
  result      jsonb               -- {pct, outcome, ok:[ids], bad:[ids]} po dokončení
);
create index if not exists sim_runs_user on public.sim_runs(user_id, scenario_id);
alter table public.sim_scenarios enable row level security;
alter table public.sim_scenario_groups enable row level security;
alter table public.sim_runs enable row level security;

create or replace function rq_private.can_see_scenario(p_id text) returns boolean
language sql stable security definer set search_path = public as $$
  select public.rq_is_admin() or (public.rq_is_member() and exists (
    select 1 from public.sim_scenarios s
      join public.sim_scenario_groups g on g.scenario_id = s.id
      join public.profiles p on p.group_id = g.group_id
     where s.id = p_id and s.status = 'ready' and p.user_id = auth.uid() and g.visible_from <= rq_private.today_cz()))
$$;

-- ---------- Studio ----------
create or replace function public.rq_sim_admin() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform rq_private.require_admin();
  return jsonb_build_object(
    'scenarios', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'module', s.module, 'title', s.title, 'summary', s.summary, 'status', s.status,
        'definition', s.definition, 'updated_at', s.updated_at,
        'groups', coalesce((select jsonb_agg(jsonb_build_object('group_id', g.group_id, 'visible_from', g.visible_from)) from public.sim_scenario_groups g where g.scenario_id = s.id), '[]'),
        -- souhrny bez účtů; průchody redakce se nepočítají
        'stats', (select jsonb_build_object('runs', count(*), 'finished', count(*) filter (where r.finished_at is not null),
            'pct_avg', round(avg((r.result->>'pct')::numeric) filter (where r.finished_at is not null)),
            'outcomes', coalesce((select jsonb_object_agg(o, n) from (select r2.result->>'outcome' o, count(*) n from public.sim_runs r2 where r2.scenario_id = s.id and r2.finished_at is not null and not r2.is_admin group by 1) x), '{}'),
            'rules', coalesce((select jsonb_object_agg(rid, jsonb_build_object('ok', ok, 'n', n)) from (
                select rid, count(*) filter (where okk) ok, count(*) n from (
                  select jsonb_array_elements_text(r3.result->'ok') rid, true okk from public.sim_runs r3 where r3.scenario_id = s.id and r3.finished_at is not null and not r3.is_admin
                  union all select jsonb_array_elements_text(r3.result->'bad'), false from public.sim_runs r3 where r3.scenario_id = s.id and r3.finished_at is not null and not r3.is_admin) y group by rid) z), '{}'))
          from public.sim_runs r where r.scenario_id = s.id and not r.is_admin)
      ) order by s.module, s.title) from public.sim_scenarios s), '[]'),
    'groups', coalesce((select jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name) order by g.name) from public.student_groups g), '[]'));
end $$;

create or replace function public.rq_sim_save_scenario(p_id text default null, p_patch jsonb default '{}') returns text
language plpgsql security definer set search_path = public as $$
declare v_id text := nullif(trim(coalesce(p_id, '')), ''); d jsonb := p_patch->'definition';
begin
  perform rq_private.require_admin();
  if v_id is null then
    if d is null or coalesce(d->>'title', '') = '' then raise exception 'Scénář potřebuje definici s názvem.'; end if;
    v_id := coalesce(nullif(p_patch->>'id', ''), 'sim-' || substr(md5(random()::text), 1, 8));
    insert into public.sim_scenarios(id, module, title, summary, status, definition, updated_by)
    values (v_id, coalesce(nullif(d->>'module', ''), 'vigilance'), d->>'title', coalesce(d->>'summary', ''), 'draft', d, auth.uid());
  else
    update public.sim_scenarios set
      definition = coalesce(d, definition),
      title = coalesce(d->>'title', title), summary = coalesce(d->>'summary', summary), module = coalesce(nullif(d->>'module', ''), module),
      status = coalesce(p_patch->>'status', status), updated_at = now(), updated_by = auth.uid()
     where id = v_id;
    if not found then raise exception 'Scénář neexistuje.'; end if;
  end if;
  return v_id;
end $$;

create or replace function public.rq_sim_delete_scenario(p_id text) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform rq_private.require_admin();
  delete from public.sim_scenarios where id = p_id;
end $$;

create or replace function public.rq_sim_set_group(p_scenario_id text, p_group_id uuid, p_visible_from date default null, p_on boolean default true) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform rq_private.require_admin();
  if p_on then
    insert into public.sim_scenario_groups(scenario_id, group_id, visible_from) values (p_scenario_id, p_group_id, coalesce(p_visible_from, rq_private.today_cz()))
    on conflict (scenario_id, group_id) do update set visible_from = excluded.visible_from;
  else
    delete from public.sim_scenario_groups where scenario_id = p_scenario_id and group_id = p_group_id;
  end if;
end $$;

-- Vymaže průchody (např. po úpravě scénáře nebo před novým semestrem) – jen souhrnně, nikoho konkrétního
create or replace function public.rq_sim_reset_runs(p_scenario_id text) returns int
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  perform rq_private.require_admin();
  delete from public.sim_runs where scenario_id = p_scenario_id; get diagnostics n = row_count;
  return n;
end $$;

-- ---------- studentská část ----------
create or replace function public.rq_sim_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.rq_is_member() then return '[]'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'module', s.module, 'title', s.title, 'summary', s.summary, 'status', s.status,
      'minutes', s.definition->'minutes', 'role', s.definition->'role',
      'runs', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'started_at', r.started_at, 'finished_at', r.finished_at, 'result', r.result) order by r.started_at desc)
                          from public.sim_runs r where r.scenario_id = s.id and r.user_id = auth.uid()), '[]'))
      order by s.module, s.title)
    from public.sim_scenarios s where rq_private.can_see_scenario(s.id)), '[]');
end $$;

create or replace function public.rq_sim_scenario(p_id text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not rq_private.can_see_scenario(p_id) then raise exception 'Simulace není dostupná.' using errcode = '42501'; end if;
  return (select jsonb_build_object('id', s.id, 'title', s.title, 'status', s.status, 'definition', s.definition,
      'run', (select to_jsonb(r) - 'user_id' from public.sim_runs r where r.scenario_id = s.id and r.user_id = auth.uid() and r.finished_at is null order by r.started_at desc limit 1))
    from public.sim_scenarios s where s.id = p_id);
end $$;

-- Uloží průběh (nový průchod, je-li p_run null). Po dokončení se uloží i výsledek.
create or replace function public.rq_sim_save_run(p_scenario_id text, p_run uuid default null, p_state jsonb default '{}', p_result jsonb default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare v uuid := p_run;
begin
  if not rq_private.can_see_scenario(p_scenario_id) then raise exception 'Simulace není dostupná.' using errcode = '42501'; end if;
  if pg_column_size(p_state) > 200000 then raise exception 'Průběh je příliš velký.'; end if;
  if v is null then
    insert into public.sim_runs(scenario_id, user_id, is_admin, state) values (p_scenario_id, auth.uid(), public.rq_is_admin(), p_state) returning id into v;
  else
    update public.sim_runs set state = p_state, updated_at = now(),
           result = coalesce(p_result, result), finished_at = case when p_result is not null then coalesce(finished_at, now()) else finished_at end
     where id = v and user_id = auth.uid() and scenario_id = p_scenario_id and finished_at is null;
    if not found then raise exception 'Průchod nelze uložit (je už uzavřený?).'; end if;
  end if;
  return v;
end $$;

create or replace function public.rq_sim_run(p_run uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  return (select to_jsonb(r) - 'user_id' from public.sim_runs r where r.id = p_run and r.user_id = auth.uid());
end $$;

do $$ declare f text; begin
  foreach f in array array['public.rq_sim_admin()', 'public.rq_sim_save_scenario(text, jsonb)', 'public.rq_sim_delete_scenario(text)',
    'public.rq_sim_set_group(text, uuid, date, boolean)', 'public.rq_sim_reset_runs(text)', 'public.rq_sim_list()', 'public.rq_sim_scenario(text)',
    'public.rq_sim_save_run(text, uuid, jsonb, jsonb)', 'public.rq_sim_run(uuid)'] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

-- Ukázkový scénář (koncept – studenti ho neuvidí, dokud ho redakce nepřepne na „připraveno“ a nezpřístupní skupině)
insert into public.sim_scenarios(id, module, title, summary, status, definition)
values ('vigilance-infuzni-pumpa', 'vigilance', $sim$Předávkování z infuzní pumpy$sim$, $sim$Nemocnice hlásí, že pumpa podala pacientovi několikanásobek dávky heparinu. Zjistěte, co se stalo, posuďte závažnost, nahlaste a rozhodněte o nápravném opatření – dřív, než se to stane jinde.$sim$, 'draft', $sim${"version": 1, "module": "vigilance", "title": "Předávkování z infuzní pumpy", "summary": "Nemocnice hlásí, že pumpa podala pacientovi několikanásobek dávky heparinu. Zjistěte, co se stalo, posuďte závažnost, nahlaste a rozhodněte o nápravném opatření – dřív, než se to stane jinde.", "minutes": 30, "role": "Vigilance výrobce – Medivia Systems s.r.o. (fiktivní výrobce)", "clock": "Den {d} od přijetí hlášení", "max_day": 25, "intro": "Jste odpovědní za vigilanci u výrobce infuzních pump. Právě vám přišlo hlášení z nemocnice. Každý krok stojí čas (počet dní je u tlačítka) – lhůty běží od okamžiku, kdy se výrobce o příhodě dozvěděl, tedy ode dne 0. Nic vám nepřipomene termín; hlídejte si ho sami.\n\nVšechny firmy, nemocnice, prostředky a údaje jsou smyšlené.", "start_messages": ["m_hlaseni"], "messages": {"m_hlaseni": {"from": "Krajská nemocnice Lipovec – ARO", "subject": "Podezření na předávkování při použití pumpy InfuSIM P3", "body": "Dobrý den,\n\nhlásíme událost s volumetrickou infuzní pumpou InfuSIM P3 (výrobní číslo SIM-P3-004417).\n\nPacientovi (68 let) byla podávána kontinuální infuze heparinu. Během podávání bolusu sestra upravila rychlost kontinuální infuze. Po zhruba dvou hodinách byla zjištěna výrazně vyšší spotřeba roztoku – pacient dostal přibližně trojnásobek naordinované dávky.\n\nDošlo ke krvácení, pacient potřeboval transfuzi a převoz na JIP. Nyní je stabilizovaný.\n\nPumpu jsme vyřadili z provozu a ponechali v původním stavu. Prosíme o vyjádření.\n\nMUDr. J. Kratochvíl, primář ARO"}, "m_detaily": {"from": "Krajská nemocnice Lipovec – zdravotnická technika", "subject": "Re: doplňující informace k pumpě SIM-P3-004417", "body": "Doplňujeme informace:\n\n- verze softwaru pumpy: 2.3 (nainstalována před třemi týdny při pravidelném servisu),\n- naordinováno 1 000 IU/h, bolus 5 000 IU; sestra během bolusu změnila kontinuální rychlost na 1 200 IU/h,\n- pumpa nehlásila žádný alarm,\n- obsluha byla proškolena, postup odpovídal návodu k použití,\n- pumpa i paměť událostí jsou k dispozici, můžeme ji poslat.\n\nIng. P. Malá, oddělení zdravotnické techniky"}, "m_vraceni": {"from": "Servisní oddělení Medivia", "subject": "Pumpa SIM-P3-004417 přijata", "body": "Pumpa z Lipovce dorazila v neporušeném stavu, protokol událostí jsme stáhli. Můžeme spustit technickou analýzu."}, "m_analyza": {"from": "Vývoj a laboratoř Medivia", "subject": "Výsledek analýzy SIM-P3-004417", "body": "Chybu jsme reprodukovali v laboratoři.\n\nPříčina: ve verzi softwaru 2.3 se při změně kontinuální rychlosti během běžícího bolusu uloží bolusová rychlost jako nová kontinuální rychlost. Pumpa pak pokračuje vysokou rychlostí bez alarmu. Verze 2.2 chybu nemá.\n\nOpravenou verzi 2.4 umíme připravit a ověřit do 10 dnů. Do té doby chybě zabrání, pokud obsluha během bolusu kontinuální rychlost nemění.\n\nPozn.: v analýze rizik je nadměrné podání (over-infusion) uvedeno jako identifikované nebezpečí."}, "m_baze": {"from": "Obchodní oddělení Medivia", "subject": "Pumpy InfuSIM P3 v provozu", "body": "Podle evidence servisu a prodeje:\n\n- v provozu je 412 pump InfuSIM P3 (Česko a Slovensko),\n- 286 z nich má software 2.3 (14 nemocnic), aktualizace se instaluje při servisu od začátku minulého měsíce,\n- 126 pump má ještě verzi 2.2.\n\nSeznam nemocnic a výrobních čísel je připravený."}, "m_trend": {"from": "Oddělení kvality Medivia", "subject": "Podobné stížnosti za poslední rok", "body": "Za poslední měsíc jsme evidovali dvě stížnosti „pumpa P3 podává rychleji, než bylo nastaveno“ (obě s verzí 2.3). Bez újmy pacientům, uzavřeno jako chyba obsluhy a doškoleno.\n\nV kontextu dnešního hlášení je to zjevně stejný problém."}, "m_mir_ok": {"from": "SÚKL – vigilance zdravotnických prostředků (simulace)", "subject": "Potvrzení přijetí hlášení", "body": "Potvrzujeme přijetí vašeho hlášení. Očekáváme další informace o výsledku šetření, případně konečnou zprávu."}, "m_fsca_ok": {"from": "Vigilance Medivia", "subject": "Bezpečnostní nápravné opatření zahájeno", "body": "Opatření je zahájeno podle vašeho rozhodnutí. Nezapomeňte na bezpečnostní upozornění (FSN) pro uživatele."}, "m_fsn_ok": {"from": "Vigilance Medivia", "subject": "Bezpečnostní upozornění odesláno", "body": "Bezpečnostní upozornění bylo rozesláno dotčeným nemocnicím. Sledujeme potvrzení o přijetí."}, "m_final_ok": {"from": "SÚKL – vigilance zdravotnických prostředků (simulace)", "subject": "Konečná zpráva přijata", "body": "Konečnou zprávu jsme přijali. Případ budeme dál sledovat v rámci dozoru nad trhem."}, "m_pripominka": {"from": "Krajská nemocnice Lipovec – ARO", "subject": "Stále čekáme na vaše vyjádření", "body": "Dobrý den, od našeho hlášení uplynulo několik dní a zatím jsme od vás nedostali žádnou reakci ani žádost o doplnění. Pumpa je stále vyřazená z provozu."}, "m_druha": {"from": "Nemocnice Bor – interní JIP", "subject": "Závažná událost s pumpou InfuSIM P3", "body": "Hlásíme úmrtí pacientky (81 let) po krvácení při léčbě heparinem. Pumpa InfuSIM P3 (výrobní číslo SIM-P3-003902, software 2.3) podle záznamu podala výrazně vyšší dávku, než bylo nastaveno – během bolusu byla měněna rychlost. Pumpu uchováváme pro šetření."}, "m_sukl": {"from": "SÚKL – vigilance zdravotnických prostředků (simulace)", "subject": "Výzva k vysvětlení", "body": "Od poskytovatele zdravotních služeb jsme obdrželi informaci o závažné nežádoucí příhodě s pumpou InfuSIM P3, ke které od vás nemáme hlášení. Vyzýváme vás k bezodkladnému vysvětlení. Zahajujeme kontrolu plnění povinností výrobce."}, "m_druha_ok": {"from": "SÚKL – vigilance zdravotnických prostředků (simulace)", "subject": "Potvrzení přijetí hlášení (Nemocnice Bor)", "body": "Potvrzujeme přijetí hlášení k události v Nemocnici Bor."}}, "actions": [{"id": "a_detaily", "group": "Zjistit víc", "label": "Vyžádat si podrobnosti od nemocnice", "days": 1, "messages": ["m_detaily"]}, {"id": "a_vraceni", "group": "Zjistit víc", "label": "Vyžádat vrácení pumpy a protokolu událostí", "days": 3, "set": {"pump_returned": true}, "messages": ["m_vraceni"]}, {"id": "a_analyza", "group": "Zjistit víc", "label": "Technická analýza pumpy", "days": 2, "when": {"done": "a_vraceni"}, "need": "Nejdřív potřebujete pumpu z nemocnice.", "set": {"root_cause": true}, "messages": ["m_analyza"]}, {"id": "a_baze", "group": "Zjistit víc", "label": "Zjistit, kolik pump a s jakým softwarem je v provozu", "days": 1, "messages": ["m_baze"]}, {"id": "a_trend", "group": "Zjistit víc", "label": "Prověřit podobné stížnosti z poslední doby", "days": 1, "messages": ["m_trend"]}, {"id": "a_zavaznost", "group": "Posoudit a nahlásit", "label": "Posoudit závažnost události", "days": 0, "choice": {"prompt": "Jak událost z Lipovce vyhodnotíte?", "var": "severity", "options": [{"id": "serious", "label": "Závažná nežádoucí příhoda – vedla k vážnému zhoršení zdravotního stavu pacienta"}, {"id": "threat", "label": "Závažné ohrožení veřejného zdraví"}, {"id": "nonserious", "label": "Nežádoucí příhoda, která není závažná – zaznamenat a sledovat v trendech"}, {"id": "user", "label": "Chyba obsluhy – nehlásit, vyřešit doškolením"}]}}, {"id": "a_mir", "group": "Posoudit a nahlásit", "label": "Podat hlášení příslušnému orgánu (SÚKL)", "days": 0, "messages": ["m_mir_ok"], "form": {"title": "Hlášení závažné nežádoucí příhody (zjednodušený formulář)", "intro": "Simulace hlášení výrobce. Uveďte, co o případu víte – počáteční hlášení může být neúplné a doplní se.", "fields": [{"id": "type", "label": "Typ hlášení", "type": "select", "options": [{"id": "initial", "label": "Počáteční"}, {"id": "combined", "label": "Kombinované počáteční a konečné"}, {"id": "final", "label": "Konečné"}]}, {"id": "class", "label": "Klasifikace", "type": "select", "options": [{"id": "serious", "label": "Závažná nežádoucí příhoda"}, {"id": "threat", "label": "Závažné ohrožení veřejného zdraví"}, {"id": "death", "label": "Úmrtí nebo nepředvídané vážné zhoršení zdravotního stavu"}]}, {"id": "content", "label": "Co hlášení obsahuje", "type": "checks", "options": [{"id": "event", "label": "Popis události a důsledků pro pacienta"}, {"id": "device", "label": "Identifikace prostředku (typ, výrobní číslo, verze softwaru)"}, {"id": "provider", "label": "Kdo událost ohlásil (poskytovatel)"}, {"id": "cause", "label": "Předběžné hodnocení příčiny (je-li známo)"}, {"id": "steps", "label": "Další plánované kroky šetření"}]}]}}, {"id": "a_mir2", "group": "Posoudit a nahlásit", "label": "Nahlásit událost z Nemocnice Bor", "days": 0, "when": {"flag": "second_incident"}, "need": "Zatím není co hlásit.", "messages": ["m_druha_ok"], "form": {"title": "Hlášení k události v Nemocnici Bor", "fields": [{"id": "class", "label": "Klasifikace", "type": "select", "options": [{"id": "serious", "label": "Závažná nežádoucí příhoda"}, {"id": "threat", "label": "Závažné ohrožení veřejného zdraví"}, {"id": "death", "label": "Úmrtí nebo nepředvídané vážné zhoršení zdravotního stavu"}]}]}}, {"id": "a_fsca", "group": "Nápravná opatření", "label": "Zahájit bezpečnostní nápravné opatření (FSCA)", "days": 2, "messages": ["m_fsca_ok"], "set": {"fsca": true}, "form": {"title": "Bezpečnostní nápravné opatření (FSCA)", "fields": [{"id": "measure", "label": "Opatření", "type": "select", "options": [{"id": "sw", "label": "Aktualizace na opravenou verzi softwaru; do té doby pokyn neměnit rychlost během bolusu"}, {"id": "recall", "label": "Stáhnout z trhu všechny pumpy InfuSIM P3"}, {"id": "warn", "label": "Jen upozornit uživatele, bez technického řešení"}]}, {"id": "scope", "label": "Kterých pump se týká", "type": "select", "options": [{"id": "v23", "label": "Pump se softwarem 2.3"}, {"id": "all", "label": "Všech pump InfuSIM P3"}, {"id": "one", "label": "Jen pumpy z Lipovce"}]}, {"id": "notify", "label": "Příslušný orgán", "type": "checks", "options": [{"id": "before", "label": "Oznámit opatření příslušnému orgánu před jeho zahájením"}]}]}}, {"id": "a_fsn", "group": "Nápravná opatření", "label": "Připravit bezpečnostní upozornění (FSN) pro uživatele", "days": 1, "when": {"done": "a_fsca"}, "need": "Nejdřív rozhodněte o nápravném opatření.", "messages": ["m_fsn_ok"], "form": {"title": "Bezpečnostní upozornění (FSN)", "intro": "Vyberte, co do upozornění patří.", "fields": [{"id": "content", "label": "Obsah upozornění", "type": "checks", "options": [{"id": "ident", "label": "Identifikace dotčených pump (typ, verze softwaru, výrobní čísla)"}, {"id": "problem", "label": "Popis problému a rizika pro pacienty"}, {"id": "now", "label": "Co mají uživatelé udělat hned (neměnit rychlost během bolusu)"}, {"id": "plan", "label": "Opatření výrobce a termín aktualizace"}, {"id": "forward", "label": "Žádost o předání všem uživatelům a potvrzení přijetí"}, {"id": "contact", "label": "Kontakt na výrobce"}, {"id": "discount", "label": "Omluva a sleva na příští nákup"}, {"id": "blame", "label": "Upozornění, že jde o chybu obsluhy"}]}]}}, {"id": "a_final", "group": "Posoudit a nahlásit", "label": "Podat konečnou zprávu", "days": 1, "when": {"all": [{"done": "a_mir"}, {"flag": "root_cause"}]}, "need": "Konečná zpráva předpokládá podané hlášení a známou příčinu.", "messages": ["m_final_ok"]}, {"id": "a_wait", "group": "Čas", "label": "Počkat jeden den", "days": 1, "repeat": true}, {"id": "a_close", "group": "Čas", "label": "Uzavřít případ a zobrazit rozbor", "days": 0, "end": true, "confirm": "Opravdu uzavřít? Další kroky už nepůjdou udělat."}], "events": [{"id": "e_pripominka", "when": {"all": [{"day_gte": 3}, {"not": {"done": "a_detaily"}}]}, "messages": ["m_pripominka"]}, {"id": "e_druha", "when": {"all": [{"day_gte": 12}, {"not": {"done": "a_fsca"}}]}, "set": {"second_incident": true}, "messages": ["m_druha"]}, {"id": "e_sukl", "when": {"all": [{"day_gte": 16}, {"not": {"done": "a_mir"}}]}, "set": {"inspection": true}, "messages": ["m_sukl"]}, {"id": "e_konec", "when": {"day_gte": 25}, "end": true}], "rules": [{"id": "r_class", "label": "Událost jste vyhodnotili jako závažnou nežádoucí příhodu", "ok": {"var": "severity", "eq": "serious"}, "good": "Pacient potřeboval transfuzi a převoz na JIP – vážné zhoršení zdravotního stavu, tedy závažná nežádoucí příhoda.", "bad": "Pacient potřeboval transfuzi a převoz na JIP – jde o vážné zhoršení zdravotního stavu, tedy závažnou nežádoucí příhodu. Nejde o chybu obsluhy (postup odpovídal návodu) ani o „nezávažnou“ příhodu; závažné ohrožení veřejného zdraví by vyžadovalo riziko pro širokou populaci.", "refs": ["MDR|Článek 2", "MDCG 2023-3"]}, {"id": "r_mir", "label": "Hlášení podáno nejpozději 15. den od přijetí informace", "ok": {"done_by": {"action": "a_mir", "day_lte": 15}}, "good": "Výrobce hlásí bezodkladně, jakmile je souvislost s prostředkem prokázaná nebo přiměřeně možná, nejpozději do 15 dnů. Na úplné výsledky šetření se nečeká – podá se počáteční hlášení.", "bad": "Lhůta běží ode dne, kdy se výrobce o příhodě dozvěděl. Hlásí se bezodkladně, nejpozději do 15 dnů – i s neúplnými informacemi (počáteční hlášení), výsledky šetření se doplní.", "refs": ["MDR|Článek 87"]}, {"id": "r_mir_class", "label": "V hlášení správná klasifikace", "only_if": {"done": "a_mir"}, "ok": {"var": "form.a_mir.class", "eq": "serious"}, "good": "Správně: závažná nežádoucí příhoda (riziko nadměrného podání je v analýze rizik uvedené, nejde tedy o nepředvídané zhoršení).", "bad": "Správná klasifikace je závažná nežádoucí příhoda. Kratší lhůty platí pro závažné ohrožení veřejného zdraví a pro úmrtí či nepředvídané vážné zhoršení zdravotního stavu.", "refs": ["MDR|Článek 87"]}, {"id": "r_info", "label": "Před rozhodováním jste si vyžádali podrobnosti", "ok": {"done": "a_detaily"}, "good": "Podrobnosti (verze softwaru, postup obsluhy) navedly šetření správným směrem.", "bad": "Bez podrobností od nemocnice nevíte o verzi softwaru ani o postupu obsluhy – a šetření se snadno stočí k „chybě obsluhy“.", "refs": ["MDR|Článek 89"]}, {"id": "r_root", "label": "Zjistili jste příčinu (technická analýza)", "ok": {"flag": "root_cause"}, "good": "Analýza odhalila chybu softwaru 2.3 – bez ní by nápravné opatření mířilo naslepo.", "bad": "Bez analýzy vrácené pumpy příčinu neznáte; výrobce musí provést šetření příhody včetně posouzení prostředku.", "refs": ["MDR|Článek 89"]}, {"id": "r_trend", "label": "Prověřili jste podobné stížnosti", "ok": {"done": "a_trend"}, "good": "Dvě dřívější stížnosti uzavřené jako „chyba obsluhy“ byly ve skutečnosti varovný signál.", "bad": "V evidenci byly dvě podobné stížnosti uzavřené jako chyba obsluhy. Sledování trendů je povinnost výrobce a pomáhá odhalit problém dřív.", "refs": ["MDR|Článek 88"]}, {"id": "r_scope", "label": "Rozsah (kolik pump a s jakým softwarem) jste znali před opatřením", "only_if": {"done": "a_fsca"}, "ok": {"done_before": ["a_baze", "a_fsca"]}, "good": "Opatření jste cílili na skutečně dotčené pumpy.", "bad": "Bez znalosti rozsahu nevíte, koho opatření týká – hrozí příliš úzké nebo zbytečně široké opatření."}, {"id": "r_fsca_time", "label": "Nápravné opatření zahájeno včas (do 11. dne)", "ok": {"done_by": {"action": "a_fsca", "day_lte": 11}}, "good": "Včasné opatření zabránilo další příhodě.", "bad": "Bez včasného opatření se stejná chyba projevila v jiné nemocnici. Ochrana dalších pacientů nečeká na dokončení všech analýz.", "refs": ["MDR|Článek 89"]}, {"id": "r_fsca_measure", "label": "Přiměřené opatření a správný rozsah", "only_if": {"done": "a_fsca"}, "ok": {"all": [{"var": "form.a_fsca.measure", "eq": "sw"}, {"var": "form.a_fsca.scope", "eq": "v23"}]}, "good": "Aktualizace softwaru u pump s verzí 2.3 a do té doby jasný pokyn – cílené a přiměřené.", "bad": "Příčina je v softwaru 2.3: přiměřené je opravit software u dotčených pump a do té doby dát uživatelům pokyn. Stažení všech pump by zbytečně ohrozilo péči, samotné upozornění bez opravy problém neodstraní."}, {"id": "r_fsca_notify", "label": "FSCA oznámeno příslušnému orgánu předem", "only_if": {"done": "a_fsca"}, "ok": {"var": "form.a_fsca.notify", "has": "before"}, "good": "Nápravné opatření se příslušnému orgánu oznamuje před jeho zahájením (kromě naléhavých případů).", "bad": "Nápravné opatření se příslušnému orgánu oznamuje před jeho zahájením, kromě naléhavých případů.", "refs": ["MDR|Článek 87", "MDR|Článek 89"]}, {"id": "r_fsn", "label": "Bezpečnostní upozornění obsahuje, co má", "only_if": {"done": "a_fsca"}, "ok": {"all": [{"var": "form.a_fsn.content", "has_all": ["ident", "problem", "now", "plan", "forward", "contact"]}, {"not": {"var": "form.a_fsn.content", "has_any": ["discount", "blame"]}}]}, "good": "Upozornění jednoznačně identifikuje pumpy, vysvětluje riziko a říká, co dělat.", "bad": "FSN má identifikovat dotčené prostředky, popsat problém a riziko, říct uživatelům, co mají dělat, uvést opatření výrobce, požádat o předání a dát kontakt. Obchodní nabídky ani svalování viny na obsluhu do něj nepatří.", "refs": ["MDR|Článek 89"]}, {"id": "r_second", "label": "Událost z Nemocnice Bor nahlášena do 10 dnů", "only_if": {"flag": "second_incident"}, "ok": {"within": {"action": "a_mir2", "from_flag": "second_incident", "days": 10}}, "good": "U úmrtí platí kratší lhůta – nejpozději 10 dnů.", "bad": "U úmrtí nebo nepředvídaného vážného zhoršení zdravotního stavu je lhůta kratší – nejpozději 10 dnů.", "refs": ["MDR|Článek 87"]}, {"id": "r_final", "label": "Podána konečná zpráva", "ok": {"done": "a_final"}, "good": "Šetření je uzavřené konečnou zprávou s příčinou a opatřeními.", "bad": "Po dokončení šetření výrobce podává konečnou zprávu se závěry a přijatými opatřeními.", "refs": ["MDR|Článek 89"]}, {"id": "r_noharm", "label": "Nedošlo k další příhodě", "ok": {"not": {"flag": "second_incident"}}, "good": "Další pacienti nebyli poškozeni.", "bad": "Chyba se projevila znovu a pacientka zemřela. Rozhodující bylo včasné opatření."}], "outcomes": [{"min": 90, "label": "Výborně zvládnuto", "text": "Postupovali jste jako zkušený výrobce: včas jste hlásili, našli příčinu a cíleně ochránili další pacienty."}, {"min": 65, "label": "Zvládnuto s výhradami", "text": "Hlavní kroky jste udělali, ale v něčem jste zaváhali – podívejte se na body níže."}, {"min": 0, "label": "Nezvládnuto", "text": "Některé zásadní povinnosti zůstaly nesplněné. Zkuste případ znovu a zaměřte se na lhůty a ochranu pacientů."}]}$sim$::jsonb)
